  idle: { START: "uploading" },
  uploading: { PAUSE: "paused", SUCCESS: "success", FAIL: "error", CANCEL: "cancelled" },
  paused: { RESUME: "uploading", CANCEL: "cancelled" },
  error: { START: "uploading" },
  success: {},
  cancelled: {},
};

function runEvents(table, start, events) {
  let state = start;
  for (const event of events) {
    const next = table[state] && table[state][event];
    if (!next) throw new Error("Invalid transition: " + event + " from " + state);
    state = next;
  }
  return state;
}

